selector_to_html = {"a[href=\"#specific-tasks\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Specific tasks<a class=\"headerlink\" href=\"#specific-tasks\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#targeting-elements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Targeting elements<a class=\"headerlink\" href=\"#targeting-elements\" title=\"Link to this heading\">#</a></h2><p>By default, use refs from the snapshot to interact with page elements.</p>", "a[href=\"references/session-management.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Session Management<a class=\"headerlink\" href=\"#browser-session-management\" title=\"Link to this heading\">#</a></h1><p>Run multiple isolated browser sessions concurrently with state persistence.</p>", "a[href=\"references/storage-state.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Storage Management<a class=\"headerlink\" href=\"#storage-management\" title=\"Link to this heading\">#</a></h1><p>Manage cookies, localStorage, sessionStorage, and browser storage state.</p>", "a[href=\"#navigation\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Navigation<a class=\"headerlink\" href=\"#navigation\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#core\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Core<a class=\"headerlink\" href=\"#core\" title=\"Link to this heading\">#</a></h3>", "a[href=\"references/running-code.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running Custom Playwright Code<a class=\"headerlink\" href=\"#running-custom-playwright-code\" title=\"Link to this heading\">#</a></h1><p>Use <code class=\"docutils literal notranslate\"><span class=\"pre\">run-code</span></code> to execute arbitrary Playwright code for advanced scenarios not covered by CLI commands.</p>", "a[href=\"#quick-start\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#example-multi-tab-workflow\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example: Multi-tab workflow<a class=\"headerlink\" href=\"#example-multi-tab-workflow\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#example-form-submission\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example: Form submission<a class=\"headerlink\" href=\"#example-form-submission\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#network\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Network<a class=\"headerlink\" href=\"#network\" title=\"Link to this heading\">#</a></h3>", "a[href=\"references/video-recording.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Video Recording<a class=\"headerlink\" href=\"#video-recording\" title=\"Link to this heading\">#</a></h1><p>Capture browser automation sessions as video for debugging, documentation, or verification. Produces WebM (VP8/VP9 codec).</p>", "a[href=\"#browser-sessions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Sessions<a class=\"headerlink\" href=\"#browser-sessions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#example-debugging-with-devtools\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example: Debugging with DevTools<a class=\"headerlink\" href=\"#example-debugging-with-devtools\" title=\"Link to this heading\">#</a></h2>", "a[href=\"references/request-mocking.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Request Mocking<a class=\"headerlink\" href=\"#request-mocking\" title=\"Link to this heading\">#</a></h1><p>Intercept, mock, modify, and block network requests.</p>", "a[href=\"references/spec-driven-testing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Spec-driven testing (plan \u2192 generate \u2192 heal)<a class=\"headerlink\" href=\"#spec-driven-testing-plan-generate-heal\" title=\"Link to this heading\">#</a></h1><p>End-to-end workflow for authoring and maintaining Playwright tests using <code class=\"docutils literal notranslate\"><span class=\"pre\">playwright-cli</span></code>. The three sections below can be used independently:</p>", "a[href=\"#tabs\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Tabs<a class=\"headerlink\" href=\"#tabs\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#raw-output\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Raw output<a class=\"headerlink\" href=\"#raw-output\" title=\"Link to this heading\">#</a></h2><p>The global <code class=\"docutils literal notranslate\"><span class=\"pre\">--raw</span></code> option strips page status, generated code, and snapshot sections from the output, returning only the result value. Use it to pipe command output into other tools. Commands that don\u2019t produce output return nothing.</p>", "a[href=\"#snapshots\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Snapshots<a class=\"headerlink\" href=\"#snapshots\" title=\"Link to this heading\">#</a></h2><p>After each command, playwright-cli provides a snapshot of the current browser state.</p>", "a[href=\"#keyboard\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Keyboard<a class=\"headerlink\" href=\"#keyboard\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#storage\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Storage<a class=\"headerlink\" href=\"#storage\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#mouse\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Mouse<a class=\"headerlink\" href=\"#mouse\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#open-parameters\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Open parameters<a class=\"headerlink\" href=\"#open-parameters\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#devtools\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">DevTools<a class=\"headerlink\" href=\"#devtools\" title=\"Link to this heading\">#</a></h3>", "a[href=\"references/playwright-tests.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Running Playwright Tests<a class=\"headerlink\" href=\"#running-playwright-tests\" title=\"Link to this heading\">#</a></h1><p>To run Playwright tests, use the <code class=\"docutils literal notranslate\"><span class=\"pre\">npx</span> <span class=\"pre\">playwright</span> <span class=\"pre\">test</span></code> command, or a package manager script. To avoid opening the interactive html report, use <code class=\"docutils literal notranslate\"><span class=\"pre\">PLAYWRIGHT_HTML_OPEN=never</span></code> environment variable.</p>", "a[href=\"#commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Commands<a class=\"headerlink\" href=\"#commands\" title=\"Link to this heading\">#</a></h2><h3>Core<a class=\"headerlink\" href=\"#core\" title=\"Link to this heading\">#</a></h3>", "a[href=\"references/tracing.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Tracing<a class=\"headerlink\" href=\"#tracing\" title=\"Link to this heading\">#</a></h1><p>Capture detailed execution traces for debugging and analysis. Traces include DOM snapshots, screenshots, network activity, and console logs.</p>", "a[href=\"#browser-automation-with-playwright-cli\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Browser Automation with playwright-cli<a class=\"headerlink\" href=\"#browser-automation-with-playwright-cli\" title=\"Link to this heading\">#</a></h1><h2>Quick start<a class=\"headerlink\" href=\"#quick-start\" title=\"Link to this heading\">#</a></h2>", "a[href=\"references/test-generation.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Test Generation<a class=\"headerlink\" href=\"#test-generation\" title=\"Link to this heading\">#</a></h1><p>Generate Playwright test code automatically as you interact with the browser.</p>", "a[href=\"references/element-attributes.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Inspecting Element Attributes<a class=\"headerlink\" href=\"#inspecting-element-attributes\" title=\"Link to this heading\">#</a></h1><p>When the snapshot doesn\u2019t show an element\u2019s <code class=\"docutils literal notranslate\"><span class=\"pre\">id</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">class</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">data-*</span></code> attributes, or other DOM properties, use <code class=\"docutils literal notranslate\"><span class=\"pre\">eval</span></code> to inspect them.</p>", "a[href=\"#save-as\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Save as<a class=\"headerlink\" href=\"#save-as\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#example-interactive-session\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example: Interactive session<a class=\"headerlink\" href=\"#example-interactive-session\" title=\"Link to this heading\">#</a></h2><p>Ask the user for UI review or design feedback. The user draws boxes on the live page and types comments; you receive the annotated screenshot, the snapshot of the marked region, and the user\u2019s notes. Use this whenever the user asks for \u201cUI review\u201d, \u201cdesign feedback\u201d, or to \u201cask the user what they think / want / mean\u201d:</p>", "a[href=\"#installation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Installation<a class=\"headerlink\" href=\"#installation\" title=\"Link to this heading\">#</a></h2><p>If global <code class=\"docutils literal notranslate\"><span class=\"pre\">playwright-cli</span></code> command is not available, try a local version via <code class=\"docutils literal notranslate\"><span class=\"pre\">npx</span> <span class=\"pre\">playwright-cli</span></code>:</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
